ALTER TABLE public.deposit_history ALTER COLUMN fee_rate SET DEFAULT 0;
CREATE OR REPLACE FUNCTION public.credit_deposit(_user_id uuid,_amount numeric,_reference text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _amount IS NULL OR _amount<=0 THEN RAISE EXCEPTION 'Invalid amount'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_reference,0)); IF EXISTS(SELECT 1 FROM public.wallet_transactions WHERE reference=_reference AND type='deposit') THEN RETURN; END IF; UPDATE public.wallets SET balance=balance+_amount,updated_at=now() WHERE user_id=_user_id; IF NOT FOUND THEN RAISE EXCEPTION 'Wallet not found'; END IF; INSERT INTO public.wallet_transactions(user_id,type,amount,reference) VALUES(_user_id,'deposit',_amount,_reference); UPDATE public.deposit_history SET gross_amount=_amount,fee_amount=0,fee_rate=0,net_amount=_amount,credited_amount=_amount,status='completed',updated_at=now() WHERE payment_id=_reference AND user_id=_user_id; END; $$;
REVOKE ALL ON FUNCTION public.credit_deposit(uuid,numeric,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.credit_deposit(uuid,numeric,text) TO service_role;